// Flatten into TASKS
const TASKS = [];
WEEKS.forEach(wk => wk.t.forEach((t, i) => {
  const flags = (t[5] || '').split(' ').filter(Boolean);
  TASKS.push({
    id: `w${wk.w}t${i + 1}`, w: wk.w, tr: t[0], h: t[1], title: t[2], d: t[3],
    res: (t[4] || '').split(',').filter(Boolean), s: flags.includes('s'),
    p: flags.find(f => /^p\d$/.test(f)) || null,
  });
}));


